-- =====================================================================
-- 修复证书编号重复: 给被覆盖的记录改编号(末尾加B)后单独导入
-- 共 17 条记录,均为专业技能证书类型
-- 执行方式: mysql -u exam_user -p'Test_1234' exam_platform < fix_dup_certs.sql
-- =====================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;


-- 验证: 专业技能证书总数应为 6931 + 17 = 6948 条
SELECT cert_type, COUNT(*) AS cnt FROM certificate WHERE cert_type = '专业技能证书';

